import { Separator } from "@/components/ui/separator"

type TimelineEvent = { date: string; dateTime?: string; title: string; description?: string }

/** Vertical timeline (after diceui timeline): aria-nova Separator as the rail. */
export default function Timeline({
  heading = "Timeline",
  events = [
    { date: "Jan 2026", dateTime: "2026-01", title: "Project started", description: "First commit and initial design tokens." },
    { date: "Apr 2026", dateTime: "2026-04", title: "Public preview", description: "Components and sections open for feedback." },
    { date: "Oct 2026", dateTime: "2026-10", title: "Stable release" },
  ],
}: {
  heading?: string
  events?: TimelineEvent[]
}) {
  return (
    <section data-slot="timeline" className="py-12">
      <div className="mx-auto max-w-3xl px-6">
        <h2 className="font-heading text-2xl font-semibold tracking-tight">{heading}</h2>
        <ol className="mt-8">
          {events.map((e, i) => (
            <li key={`${e.date}-${e.title}`} className="grid grid-cols-[auto_1fr] gap-x-4">
              <div className="flex flex-col items-center">
                <span aria-hidden="true" className="mt-1.5 size-2.5 shrink-0 rounded-full border-2 border-primary bg-background" />
                {i < events.length - 1 && <Separator orientation="vertical" className="my-1 flex-1" />}
              </div>
              <div className="pb-8">
                <time dateTime={e.dateTime} className="text-sm text-muted-foreground">
                  {e.date}
                </time>
                <h3 className="mt-1 font-medium">{e.title}</h3>
                {e.description && <p className="mt-1 text-sm text-muted-foreground">{e.description}</p>}
              </div>
            </li>
          ))}
        </ol>
      </div>
    </section>
  )
}
